    lui t1, 0xa0044
    sw t1, 0x10(s0)
    lw t1, 0x20(s0)
    addi t1, zero, 272
    sw t1, 0x00(s0)
    addi t1, zero, 31
    sw t1, 0x10(s0)
    sw t1, 0x10(s0)
    lui t1, 0xa0044
    sw t1, 0x10(s0)
    lw t1, 0x20(s0)
    addi t1, zero, 272
    sw t1, 0x00(s0)
    addi t1, zero, 511
    sw t1, 0x10(s0)
